#!/bin/bash
# 올리기 전 반드시 통과해야 하는 관문(11-14 23:10 대표님 「확실히 보려면 어떻게 해야 해?」)
# 사용: bash 점검관문.sh 폴더   → 하나라도 실패면 「관문 실패」 + 0 아닌 끝 번호
D=${1:-/home/claude/v85t}; F=0; pkill -f chrome 2>/dev/null
echo "① 안 때리는 병사"; R=$(timeout 60 node 공격재기.js $D 13 2>&1); echo "$R" | head -3 | cut -c1-160; echo "$R" | grep -q "한번도안때림[1-9]" && { echo "  ✗ 안 때리는 병사 있음"; F=1; }; echo "$R" | grep -q "오류 0" || { echo "  ✗ 오류"; F=1; }
pkill -f chrome 2>/dev/null
echo "② 보스 동작"; sleep 2; R=$(timeout 80 node 보스재기.js $D 20 2>&1); echo "$R" | grep -q "오류 0" || { sleep 3; R=$(timeout 80 node 보스재기.js $D 20 2>&1); }; echo "$R" | grep -c "slam" | sed 's/^/  내려찍기 횟수 /'; echo "$R" | grep -q "slam" || { echo "  ✗ 보스가 안 때림"; F=1; }; echo "$R" | grep -q "오류 0" || { echo "  ✗ 오류"; F=1; }
pkill -f chrome 2>/dev/null
echo "③ 잘린 글자 · 화면 밖"; R=$(timeout 90 node 잘림점검.js $D 관문 2>&1); C=$(echo "$R" | grep -v "^[a-z]* goal" | grep -c "잘림:\|밖:"); echo "  잘림 줄 $C"; [ "$C" -gt 0 ] && { echo "$R" | grep "잘림:\|밖:" | head -5; F=1; }; echo "$R" | grep -q "오류 0" || { echo "  ✗ 오류"; F=1; }
pkill -f chrome 2>/dev/null
echo "④ 처음 10분"; R=$(timeout 200 node 첫10분재기.js $D 4 10 2>&1); echo "$R" | tail -2; echo "$R" | grep -q "오류 0" || { echo "  ✗ 오류"; F=1; }; G=$(echo "$R" | grep -o "가장 긴 틈 [0-9]*" | grep -o "[0-9]*$"); [ "${G:-999}" -gt 120 ] && { echo "  ✗ 2분 넘게 새것 없음"; F=1; }
pkill -f chrome 2>/dev/null
echo "⑤ 글자 상자 겹침(대표님 폰 360×593 · 1판부터 실제 흐름 2분 반)"; R=$(timeout 210 node 겹침재기.js $D 0 2>&1); echo "$R" | grep "겹침" | head -5; echo "$R" | grep -q "오류 0" || { echo "  ✗ 오류"; F=1; }; echo "$R" | grep "^겹침" | sed -E 's/.* ([0-9]+)번\(([0-9]+)%\)/\1 \2/' | awk '$1>=10 && $2>=30{f=1} END{exit !f}' && { echo "  ✗ 10번 넘게 30% 넘게 겹치는 짝 있음"; F=1; }
pkill -f chrome 2>/dev/null
echo "⑥ 눈 확인(고친 뒤 찍은 폰 화면을 열어 보고 본 것을 적었나)"; python3 -I 눈확인검사.py $D || F=1
echo "⑦ 장르 대조표(필수 칸이 비면 실패)"; T=../장르대조표.md; if [ ! -f $T ]; then echo "  ✗ 장르대조표.md 없음"; F=1; else N=$(grep "| 필수 |" $T | awk -F"|" '{print $7}' | grep -c "⬜"); echo "  필수 칸 중 없음 $N"; [ "$N" -gt 0 ] && { grep "| 필수 |" $T | awk -F"|" '$7 ~ /⬜/ {print "  ✗"$2}'; F=1; }; fi
echo "⑧ 작업 순서(대표님 말씀 횟수 순 · 맨 위부터) — 11-15 19:32 「일 순서 있지 않어?」"; python3 순서검사.py ../작업순서.md ${JR:-/home/claude/jr/작업기록.md} || F=1
echo "⑨ 타격 리듬(싸움 20초를 숫자로) — 11-15 19:30 「타격감 없고 따따따닥」: 멈칫 초당 1.2 이하 · 멈춘 시간 6% 이하 · 피해 숫자 초당 6 이하 · 숫자끼리 붙어 읽힘 0쌍(「19150」 「291276」) · 숫자가 단추 · 알림 뒤에 숨음 0번 · 영웅이 흰 빛에 덮인 순간 5% 이하 · 영웅이 앞 유닛에 가린 정도 30% 이하 · 우리 편 · 적 뒤섞임 15% 이하(21:51 버섯커) · 영웅 요요 20초에 15번 이하(22:32)"; R=$(timeout 100 node 타격리듬.js $1 2>/dev/null | tail -1); echo "  $R"; python3 -c "import json,sys; r=json.loads(sys.argv[1]); b=[]; r['멈칫_초당']>1.2 and b.append('멈칫 %s/초'%r['멈칫_초당']); float(r['멈춘_비율'][:-1])>6 and b.append('멈춘 시간 '+r['멈춘_비율']); r['숫자_초당']>6 and b.append('숫자 %s/초'%r['숫자_초당']); r.get('숫자_붙음',0)>0 and b.append('숫자 붙어 읽힘 %s쌍 %s'%(r['숫자_붙음'],r.get('붙은_예'))); r.get('숫자_단추에가림',0)>0 and b.append('숫자가 단추 · 알림 뒤에 숨음 %s번 %s'%(r['숫자_단추에가림'],r.get('가림_예'))); wb=[int(x) for x in str(r.get('영웅_흰빛덮임','0/1')).split('/')]; wb[1] and wb[0]/wb[1]>0.05 and b.append('영웅이 흰 빛에 덮임 %s'%r['영웅_흰빛덮임']); r.get('영웅_가림','0%')!='-' and int(str(r.get('영웅_가림','0%'))[:-1])>30 and b.append('영웅이 앞 유닛에 가림 %s'%r['영웅_가림']); r.get('영웅_요요',0)>15 and b.append('근접 영웅이 뛰었다 돌아오는 요요 %s번(20초)'%r['영웅_요요']); r.get('진영섞임','0%')!='-' and int(str(r.get('진영섞임','0%'))[:-1])>15 and b.append('우리 편 · 적이 뒤섞임 %s(버섯커처럼 왼쪽 · 오른쪽 갈려야)'%r['진영섞임']); print('  ✗ 따따따닥: '+' · '.join(b) if b else '  리듬 통과'); sys.exit(1 if b else 0)" "$R"; G=$?; python3 관문묶음.py ../작업순서.md ⑨ $G || F=1
echo "⑩ 지적장부(줄마다 자동 확인이 있나 · 「눈」만이면 실패) — 11-15 19:40 「말 아닌 확실하게 할 수밖에 없게끔 강제」"; python3 장부검사.py ../지적장부.md || F=1
echo "⑪ 밸런스(과금 흉내 30일 × 씨앗 8) — 11-14 20:30 · 11-15 18:08 말씀"; python3 밸런스관문.py; G=$?; python3 관문묶음.py ../작업순서.md ⑪ $G || F=1
echo "⑫ 동작(영웅이 그림 한 장 = 종이인지) — 11-15 19:36 「종이가 움직이냐?」"; python3 동작검사.py ../art; G=$?; python3 관문묶음.py ../작업순서.md ⑫ $G || F=1
echo "⑭ 화면 크기 4가지(작은 폰 · 대표님 폰 · 큰 폰 · PC) — A2 「판이 안 보인다 · 좁다」 · A4 「작은 폰 큰 폰 · 웹」: 잘린 유닛 0 · 전장 높이 40% 이상 · 영웅 키 60px 이상"; R=$(timeout 200 node 화면크기.js $1 2>/dev/null); echo "$R" | sed 's/^/  /'; echo "$R" | python3 -c "import json,sys; L=[json.loads(l) for l in sys.stdin if l.strip()]; b=[o['화면']+' 잘림 %s'%o['잘린유닛'] for o in L if o['잘린유닛']>0]+[o['화면']+' 전장 %s%%'%o['전장높이비'] for o in L if o['전장높이비']<40]+[o['화면']+' 영웅 %spx'%o['영웅키px'] for o in L if o['영웅키px']<60]; print('  ✗ '+' · '.join(b) if b or len(L)<4 else '  화면 크기 통과'); sys.exit(1 if b or len(L)<4 else 0)"; G=$?; python3 관문묶음.py ../작업순서.md ⑭ $G || F=1
echo "⑮ 소리(배경음 두 곡 -16 LUFS · 강화 띵 · 연타하면 음이 올라감 · 플레이 영상에 소리 줄 있고 끊김 0.6초 이하) — 11-15 19:49 「게임 배경음 · 업글할 때 클릭 사운드 필수」"; python3 소리검사.py $D ${SNDV:-소리} | sed 's/^/  /'; G=${PIPESTATUS[0]}; python3 관문묶음.py ../작업순서.md ⑮ $G || F=1
echo "⑯ 입장(1-1 첫 화면부터 일으켜라 9번 · 영웅 합류 · 판 넘김 3번을 매 프레임 잼) — B8 「병사들 입장할 때 자연스럽게」 · A5 「지들끼리 겹쳐 보임」: 순간이동 0 · 화면 가운데 「뿅」 0 · 영웅 포개짐 5% 이하 · 새 유닛 몰림 12% 이하"; R=$(timeout 120 node 입장재기.js $D 2>/dev/null | tail -1); echo "  $R"; python3 -c "import json,sys; r=json.loads(sys.argv[1]); b=[]; sum(r['순간이동'].values()) and b.append('순간이동 %s'%r['순간이동']); sum(r['갑자기나타남'].values()) and b.append('뿅 %s %s'%(r['갑자기나타남'],r['나타남_예'][:3])); r['영웅_포개짐']!='-' and int(r['영웅_포개짐'][:-1])>5 and b.append('영웅 포개짐 '+r['영웅_포개짐']); r['몰림_비율']!='-' and int(r['몰림_비율'][:-1])>12 and b.append('몰림 '+r['몰림_비율']); r.get('오류',0) and b.append('오류 %s'%r['오류']); print('  ✗ 입장: '+' · '.join(b) if b else '  입장 통과'); sys.exit(1 if b else 0)" "$R"; G=$?; python3 관문묶음.py ../작업순서.md ⑯ $G || F=1
echo "⑰ 별 올림 연출(★2 · ★3을 실제 뽑기 흐름으로 띄워 잼) — 순서 #7: 별 칸 6 · 새 별 박힘 · 띵 계단 · ★3 불꽃 · 불똥 · 새 힘 글 · 끝나면 결과 카드"; R=$(timeout 150 node 별연출재기.js $D 2>/dev/null | tail -1); python3 별연출검사.py "$R"; G=$?; python3 관문묶음.py ../작업순서.md ⑰ $G || F=1
echo "⑱ 효과음(1-1부터 3-10 싸움까지 45초 녹음) — 순서 #8: 소리마다 -40dB 이상(묻힘 없음) · 자주 나는 소리 -20dB 이하 · 깨짐 0"; R=$(timeout 150 node 효과음재기.js $D 2>/dev/null | grep "^{" | tail -1); python3 효과음검사.py "$R"; G=$?; python3 관문묶음.py ../작업순서.md ⑱ $G || F=1
echo "⑲ 진형 고정 자리(3-10 20초 · 소환수 4 · 영웅 4) — 11-16 00:25 「겹치는 싸움 말고 완전 따로 포지션」 · 00:33 「같은 자리 2마리여도 안 겹치게」: 몸 겹침 5% 이하 · 자리 벗어남 · 병과 바뀜 0 · 앞줄 무너지면 영웅이 맞음"; R=$(timeout 120 node 진형재기.js $D 2>/dev/null | tail -1); python3 진형검사.py "$R"; G=$?; python3 관문묶음.py ../작업순서.md ⑲ $G || F=1
echo "⑳ 그림 기준(순서 #10 · 01:40 대표님 결정 시안 1번 「2등신 귀여운 + 어두운 보랏빛」): 전투에 그려지는 그림 36개 모두 시안 참고로 새로 그림 · 테두리 · 우리 편 보라 / 적 은색"; python3 그림관문.py $D; G=$?; python3 관문묶음.py ../작업순서.md ⑳ $G || F=1
echo "㉑ 망자 거인 · 자랑 카드(순서 #11 · #12 · 03:13 대표님 「어케 잼게 바꾸련지」): 보스 잡으면 3초 안에 보라 망자 거인이 일어나고 싸움 중 내려찍고 · 자랑 단추 반짝 · 카드에 거인"; R=$(timeout 150 node 거인재기.js $D | tail -1); python3 거인검사.py "$R"; G=$?; python3 관문묶음.py ../작업순서.md ㉑ $G || F=1
echo "㉒ 약점 끊기(순서 #12 · 01:42 「보스전 이거도 안 땡기게」): 보스 큰 기술 앞에 약점이 뜨고(2번↑) · 누르면 체력 4%↑ · 시간 +1.5초↑ · 그 기술 취소 · 안 누르면 기술이 터짐"; R=$(timeout 150 node 약점재기.js $D 관문 | tail -1); python3 약점검사.py "$R"; G=$?; python3 관문묶음.py ../작업순서.md ㉒ $G || F=1
echo "㉓ 켜는 시간(순서 #13): 빠른 3G 1.6Mbps · CPU 4배 느림 — 첫 글자 3초 · 「누르세요」 12초 · 누른 뒤 새 그림 싸움 1초 안"; R=$(timeout 300 node 켜는시간.js $D | tail -1); python3 켜는검사.py "$R"; G=$?; python3 관문묶음.py ../작업순서.md ㉓ $G || F=1
