echo "㉚ 적 떼 · 적 기술 · 적 빛깔 · 승급 모습 · 렉(11-16 13:58~13:59 대표님 「적은 너무 없는 거 아님 · 적들도 화려한 스킬 · 캐릭터도 다양」 · 11:30 「모습도 바뀌는 거야?」 · 12:04 「렉 없이」)"; A=$(timeout 90 node 적떼찍기.js $D pc 관문 | tail -1); B=$(timeout 90 node 적떼찍기.js $D 폰 관문 | tail -1); C=$(CPU=1 timeout 100 node 프레임재기.js $D | tail -1); python3 적떼검사.py "$A" "$B" "$C"; G=$?; python3 관문묶음.py ../작업순서.md ㉚ $G || F=1
echo "⑬ 직접 플레이 영상(고친 뒤 찍고 본 것 적기) — 11-15 19:56 「기능들도 전부 영상으로 직접 플레이 체크」"; python3 영상확인검사.py $1 || F=1
[ $F = 0 ] && echo "관문 통과" || { echo "관문 실패"; exit 1; }
